public class IndexAccessDemo {
    public static void main(String[] args) {
        int[] scores = {10, 20, 30};

        System.out.println("First element (index 0): " + scores[0]);
        System.out.println("Last element (index " + (scores.length - 1) + "): " + scores[scores.length - 1]);

        // Modifying an element:
        scores[1] = 99;
        System.out.println("Updated middle element: " + scores[1]);

        // Accessing scores[3] or scores[-1] throws:
        // java.lang.ArrayIndexOutOfBoundsException: Index 3 out of bounds for length 3
    }
}

