    public static void main(String[] args) {
        int[] arr = {10, 20, 30};
        // Test index 2 and index 5
    }
}

practiceProblems.solutionCode:
public class Main {
    public static int safeGet(int[] arr, int index, int defaultValue) {
        if (index >= 0 && index < arr.length) {
            return arr[index];
        }
        return defaultValue;
    }

    public static void main(String[] args) {
        int[] arr = {10, 20, 30};
        System.out.println("Index 2: " + safeGet(arr, 2, -1));
        System.out.println("Index 5: " + safeGet(arr, 5, -1));
    }
}

