practiceProblems.solutionCode:
public class Main {
    public static int getMiddle(int[] arr) {
        return arr[arr.length / 2];
    }

    public static void main(String[] args) {
        int[] arr = {4, 7, 9, 12, 15};
        System.out.println("Middle: " + getMiddle(arr));
    }
}
